namespace ghidra.util.charset.picker;




using docking.widgets.table;
using ghidra.util.charset;
using ghidra.util.charset;

class CharsetTableModel : AbstractSortedTableModel<CharsetTableRow> {

	static int NAME_COL = 0;
	static int COMMENT_COL = 1;
	static int FIXEDLEN_COL = 2;
	static int MINLEN_COL = 3;
	static int MAXLEN_COL = 4;
	static int SCRIPTS_COL = 5;

	static string[] COL_NAMES =
		new string[] { "Name", "Description", "Fixed Length", "Min BPC", "Max BPC", "Scripts" };

	private List<CharsetTableRow> charsets = new();

	public CharsetTableModel() {
		CharsetInfoManager.getInstance()
				.getCharsets()
				.stream()
				.map(csi => new CharsetTableRow(csi, getScriptsString(csi.getScripts())))
				.forEach(charsets.add);
	}

	private static string getScriptsString(Set<UnicodeScript> scripts) {
		StringBuilder sb = new StringBuilder();
		foreach (UnicodeScript script in scripts) {
			if (!sb.isEmpty()) {
				sb.append(", ");
			}
			sb.append(script.name());
		}
		return sb.toString();
	}

	public int findCharset(CharsetInfo csi) {
		for (int i = 0; i < charsets.size(); i++) {
			CharsetTableRow row = charsets.get(i);
			if (row.csi().getName().equals(csi.getName())) {
				return i;
			}
		}
		return -1;
	}

	/* @Override */
	public string getName() {
		return "Charsets";
	}

	/* @Override */
	public int getColumnCount() {
		return COL_NAMES.length;
	}

	/* @Override */
	public string getColumnName(int column) {
		return 0 <= column && column < COL_NAMES.length ? COL_NAMES[column] : "<<unknown>>";
	}

	/* @Override */
	public Class<object> getColumnClass(int columnIndex) {
		switch (columnIndex) {
			case NAME_COL:
				return typeof(string);
			case COMMENT_COL:
				return typeof(string);
			case FIXEDLEN_COL:
				return typeof(Boolean);
			case MINLEN_COL:
				return typeof(Integer);
			case MAXLEN_COL:
				return typeof(Integer);
			case SCRIPTS_COL:
				return typeof(string);
		}
		return typeof(object);
	}

	/* @Override */
	public bool isSortable(int columnIndex) {
		return true;
	}

	/* @Override */
	public List<CharsetTableRow> getModelData() {
		return charsets;
	}

	/* @Override */
	public object getColumnValueForRow(CharsetTableRow row, int column) {
		switch (column) {
			case NAME_COL: return row.csi().getName();
			case COMMENT_COL: return row.csi().getComment();
			case FIXEDLEN_COL: return row.csi().hasFixedLengthChars();
			case MINLEN_COL: return row.csi().getMinBytesPerChar();
			case MAXLEN_COL: return row.csi().getMaxBytesPerChar();
			case SCRIPTS_COL: return row.scripts();
			default: "???";
		};
	}

}
